fn normalize_hex(id: &str, len: usize, what: &str) -> Result<String> {
    let t = id.trim();
    let t = t
        .strip_prefix("0x")
        .or_else(|| t.strip_prefix("0X"))
        .unwrap_or(t);
    if t.is_empty() || t.len() > len || !t.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(Error::validation(format!("invalid {what} {id:?}")));
    }
    let out = format!("{:0>len$}", t.to_ascii_lowercase());
    if out.bytes().all(|b| b == b'0') {
        return Err(Error::validation(format!("invalid {what}: all zeros")));
    }
    Ok(out)
}

/// Lower-cases and left-pads a trace id to 32 hex characters (64-bit ids from Zipkin/Datadog).
pub fn normalize_trace_id(id: &str) -> Result<String> {
    normalize_hex(id, 32, "trace id")
}

/// [`normalize_trace_id`] for hex ids; any other non-empty id (a native id such as a
/// SkyWalking segment/trace id) is returned trimmed and unchanged. Use it where a backend's own
/// ids must not be rejected.
pub fn normalize_trace_id_or_native(id: &str) -> Result<String> {
    native_or(id, 32, "trace id")
}

/// [`normalize_span_id`] for hex ids; any other non-empty id is returned trimmed and unchanged.
pub fn normalize_span_id_or_native(id: &str) -> Result<String> {
    native_or(id, 16, "span id")
}

fn native_or(id: &str, len: usize, what: &str) -> Result<String> {
    let t = id.trim();
    if t.is_empty() {
        return Err(Error::validation(format!("invalid {what}: empty")));
    }
    let hex = t
        .strip_prefix("0x")
        .or_else(|| t.strip_prefix("0X"))
        .unwrap_or(t);
    if hex.len() <= len && !hex.is_empty() && hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return normalize_hex(t, len, what);
    }
    Ok(t.to_string())
}

/// Lower-cases and left-pads a span id to 16 hex characters.
pub fn normalize_span_id(id: &str) -> Result<String> {
    normalize_hex(id, 16, "span id")
}

/// Sorts spans by start time, then span id.
pub fn sort_spans(spans: &mut [Span]) {
    spans.sort_by(|a, b| {
        a.start_micros
            .cmp(&b.start_micros)
            .then_with(|| a.span_id.cmp(&b.span_id))
    });
}

/// Builds the span forest: roots are spans without a parent or whose parent is not present.
pub fn build_tree(spans: &[Span]) -> Vec<SpanNode> {
    let mut sorted = spans.to_vec();
    sort_spans(&mut sorted);
    let ids: std::collections::HashSet<&str> = sorted.iter().map(|s| s.span_id.as_str()).collect();
    let mut children: BTreeMap<String, Vec<Span>> = BTreeMap::new();
    let mut roots = Vec::new();
    for s in &sorted {
        match &s.parent_span_id {
            Some(p) if ids.contains(p.as_str()) && p != &s.span_id => {
                children.entry(p.clone()).or_default().push(s.clone())
            }
            _ => roots.push(s.clone()),
        }
    }
    fn attach(span: Span, children: &mut BTreeMap<String, Vec<Span>>) -> SpanNode {
        let kids = children.remove(&span.span_id).unwrap_or_default();
        SpanNode {
            children: kids.into_iter().map(|k| attach(k, children)).collect(),
            span,
        }
    }
    roots
        .into_iter()
        .map(|r| attach(r, &mut children))
        .collect()
}

fn micros(t: SystemTime) -> u64 {
    t.duration_since(UNIX_EPOCH)
        .map(|d| d.as_micros() as u64)
        .unwrap_or(0)
}

fn kv_attributes(kvs: &[opentelemetry::KeyValue]) -> Attributes {
    kvs.iter()
        .map(|kv| (kv.key.to_string(), attr_value(&kv.value)))
        .collect()
}

fn attr_value(v: &opentelemetry::Value) -> AttrValue {
    use opentelemetry::{Array, Value};
    match v {
        Value::Bool(b) => (*b).into(),
        Value::I64(i) => (*i).into(),
        Value::F64(f) => (*f).into(),
        Value::String(s) => s.as_str().into(),
        Value::Array(Array::Bool(a)) => a.clone().into(),
        Value::Array(Array::I64(a)) => a.clone().into(),
        Value::Array(Array::F64(a)) => a.clone().into(),
        Value::Array(Array::String(a)) => a
            .iter()
            .map(|s| s.as_str().to_string())
            .collect::<Vec<_>>()
            .into(),
        other => other.to_string().into(),
    }
}

impl Span {
    /// Converts finished SDK span data (as received by a `SpanExporter`).
    pub fn from_span_data(data: &opentelemetry_sdk::trace::SpanData, service_name: &str) -> Span {
        use opentelemetry::trace::{SpanId, Status};
        let start = micros(data.start_time);
        let end = micros(data.end_time).max(start);
        let status = match &data.status {
            Status::Unset => SpanStatus::default(),
            Status::Ok => SpanStatus {
                code: StatusCode::Ok,
                message: None,
            },
            Status::Error { description } => SpanStatus {
                code: StatusCode::Error,
                message: Some(description.to_string()).filter(|d| !d.is_empty()),
            },
        };
        Span {
            trace_id: data.span_context.trace_id().to_string(),
            span_id: data.span_context.span_id().to_string(),
            parent_span_id: (data.parent_span_id != SpanId::INVALID)
                .then(|| data.parent_span_id.to_string()),
            name: data.name.to_string(),
            kind: SpanKind::from(&data.span_kind),
            service_name: service_name.to_string(),
            start_micros: start,
            end_micros: end,
            duration_micros: end - start,
            status,
            attributes: kv_attributes(&data.attributes),
            events: data
                .events
                .iter()
                .map(|e| SpanEvent {
                    name: e.name.to_string(),
                    time_micros: micros(e.timestamp),
                    attributes: kv_attributes(&e.attributes),
                })
                .collect(),
            links: data
                .links
                .iter()
                .map(|l| SpanLink {
                    trace_id: l.span_context.trace_id().to_string(),
                    span_id: l.span_context.span_id().to_string(),
                    attributes: kv_attributes(&l.attributes),
                })
                .collect(),
        }
    }
}

impl Trace {
    /// A trace with spans sorted.
    pub fn new(trace_id: impl Into<String>, mut spans: Vec<Span>) -> Self {
        sort_spans(&mut spans);
        Trace {
            trace_id: trace_id.into(),
            spans,
        }
    }

    /// The span tree.
    pub fn tree(&self) -> Vec<SpanNode> {
        build_tree(&self.spans)
    }

    /// Names of the direct children of every span named `parent_name`.
    pub fn children_of(&self, parent_name: &str) -> Vec<String> {
        let parents: Vec<&str> = self
            .spans
            .iter()
            .filter(|s| s.name == parent_name)
            .map(|s| s.span_id.as_str())
            .collect();
        self.spans
            .iter()
            .filter(|s| {
                s.parent_span_id
                    .as_deref()
                    .is_some_and(|p| parents.contains(&p))
            })
            .map(|s| s.name.clone())
            .collect()
    }

    /// Summary: root = first span without a present parent.
    pub fn summary(&self) -> TraceSummary {
        let roots = self.tree();
        let root = roots.first().map(|n| &n.span);
        let start = self.spans.iter().map(|s| s.start_micros).min().unwrap_or(0);
        let end = self
            .spans
            .iter()
            .map(|s| s.end_micros)
            .max()
            .unwrap_or(start);
        TraceSummary {
            trace_id: self.trace_id.clone(),
            root_service_name: root.map(|s| s.service_name.clone()),
            root_name: root.map(|s| s.name.clone()),
            start_micros: start,
            duration_micros: end.saturating_sub(start),
            span_count: self.spans.len(),
        }
    }
}

/// Accepts `status` as `{code, message?}` (wire form) or a bare code string.
fn de_status<'de, D: Deserializer<'de>>(d: D) -> std::result::Result<SpanStatus, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Wire {
        Code(StatusCode),
        Object {
            code: StatusCode,
            #[serde(default)]
            message: Option<String>,
        },
    }
    Ok(match Wire::deserialize(d)? {
        Wire::Code(code) => SpanStatus {
            code,
            message: None,
        },
        Wire::Object { code, message } => SpanStatus { code, message },
    })
}

/// Accepts vendor kind spellings on input.
fn de_kind<'de, D: Deserializer<'de>>(d: D) -> std::result::Result<SpanKind, D::Error> {
    Ok(SpanKind::parse(&String::deserialize(d)?))
}
